WITH with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM sessions), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT id, started_at, is_new_session, burst_id FROM sessionized
